  "components.checkin.nfc": ["NFC-CHECK-IN","NFC CHECK-IN","NFC GİRİŞİ","تسجيل الدخول عبر NFC","NFC PRIJAVA","CHECK-IN NFC","NFC-CHECK-IN"],
  "components.checkin.title": ["Bitte am Terminal einchecken","Please check in at the terminal","Lütfen terminalde giriş yap","سجّل الدخول عند الجهاز","Prijavi se na terminalu","Effettua il check-in al terminale","Checke am Terminal ein."],
  "components.checkin.real": ["Halte dein Smartphone nah an das Lesefeld des Terminals.","Hold your phone close to the terminal’s reader.","Telefonunu terminalin okuyucusuna yaklaştır.","قرّب هاتفك من قارئ الجهاز.","Približi telefon čitaču terminala.","Avvicina lo smartphone al lettore del terminale.","Halte dein Handy nah an das Lesefeld."],
  "components.checkin.demo": ["Halte dein Smartphone nah an das Lesefeld des Terminals. Hier simuliert.","Hold your phone close to the terminal’s reader. Simulated here.","Telefonunu terminalin okuyucusuna yaklaştır. Burada simüle edilir.","قرّب هاتفك من قارئ الجهاز. هنا تتم المحاكاة.","Približi telefon čitaču terminala. Ovdje je simulirano.","Avvicina lo smartphone al lettore del terminale. Qui è simulato.","Halte dein Handy nah an das Lesefeld. Hier ist es eine Demo."],
  "components.checkin.hold": ["Handy kurz ans Lesefeld halten","Briefly hold your phone to the reader","Telefonu kısaca okuyucuya tut","قرّب الهاتف من القارئ للحظة","Nakratko prisloni telefon uz čitač","Avvicina brevemente il telefono al lettore","Halte das Handy kurz ans Lesefeld."],
  "components.checkin.try": ["Teste den Check-in mit einer simulierten Fahrt.","Try checking in with a simulated ride.","Simüle edilen bir yolculukla girişi dene.","جرّب تسجيل الدخول برحلة محاكاة.","Isprobaj prijavu uz simuliranu vožnju.","Prova il check-in con una corsa simulata.","Teste den Check-in mit einer Demo-Fahrt."],
